import {DEFAULTS,NETWORKS,SAMPLE,payload,consumption,plan,legEnergy,validate} from './engine.mjs';
import {connect,discover,verify,draw} from './google.mjs';
import {exportTrip} from './export.mjs';
const $=id=>document.getElementById(id);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let settings=structuredClone(DEFAULTS),route=structuredClone(SAMPLE),result=null,excluded=[],baseRoute=null,busy=false,planned=null,dirty=false;
try{const saved=JSON.parse(localStorage.getItem('atto-settings-v1'));if(saved)settings={...settings,...saved,mode:'sample',origin:DEFAULTS.origin,destination:DEFAULTS.destination,tariffs:{...DEFAULTS.tariffs,...saved.tariffs}};}catch{}
const numeric=['battery','reserve','buffer','speed','people','personWeight','luggage','baseConsumption','headwind','temperature'];
function populate(){for(const k of [...numeric,'origin','destination','payloadOverride'])$(k).value=settings[k];$('fastOnly').checked=settings.fastOnly;renderNetworks();$('tariffs').innerHTML=NETWORKS.map(n=>`<label>${n} assumed price<div class="unit-input"><input id="price-${n}" type="number" min="0.1" max="100" step="0.1" value="${Number(settings.tariffs[n])}"><span>₺/kWh</span></div></label>`).join('');syncLabels();}
function read(){for(const k of numeric)settings[k]=Number($(k).value);for(const k of ['origin','destination','payloadOverride'])settings[k]=$(k).value.trim();settings.fastOnly=$('fastOnly').checked;for(const n of NETWORKS)settings.tariffs[n]=Number($('price-'+n).value);try{localStorage.setItem('atto-settings-v1',JSON.stringify(settings));}catch{}return settings;}
function syncLabels(){read();$('batteryValue').textContent=settings.battery;$('speedValue').textContent=settings.speed;$('payloadBadge').textContent=Math.round(payload(settings))+' kg';}
function renderNetworks(){$('networks').innerHTML=NETWORKS.map(n=>`<button type="button" data-network="${n}" aria-pressed="${settings.networks.includes(n)}" class="network ${settings.networks.includes(n)?'active':''}">${n}</button>`).join('');}
const time=m=>`${Math.floor(m/60)}h ${Math.round(m%60)}m`;const money=v=>Math.round(v).toLocaleString('tr-TR');
function mapsUrl(stop){const u=new URL('https://www.google.com/maps/dir/');u.searchParams.set('api','1');u.searchParams.set('destination',stop?(stop.location?`${stop.location.lat},${stop.location.lng}`:`${stop.network} ${stop.name} İzmir Yönü`):settings.destination);if(stop?.location)u.searchParams.set('destination_place_id',stop.id);u.searchParams.set('travelmode','driving');if(!stop)u.searchParams.set('origin',settings.origin);return u.href;}
function mapSetup(){$('mapArt').innerHTML=`<div class="map-setup"><span class="map-symbol">↗</span><h2>Your route on Google Maps</h2><p>Connect Google Maps to see real roads, terrain and your charging stops here.</p><button type="button" id="mapConnect" class="primary">Connect Google Maps ↗</button><small>A Google Maps API key is needed for the in-app map.<br>Sending your stops to Google Maps is available without one.</small></div>`;$('mapConnect').onclick=()=>$('connectionDialog').showModal();}
function invalidate(){dirty=true;$('mapButton').disabled=true;$('exportRoute').disabled=true;$('exportStatus').textContent='Recalculate to export your updated settings.';}
function showExport(){if(!result||!planned||dirty)return;const trip=exportTrip(planned.origin,planned.destination,result.stops);$('exportSummary').textContent=`${planned.origin} → ${planned.destination} · ${trip.count} charging stops`;$('exportWarning').textContent=route.source==='sample'?'Sample itinerary: station locations and distances are not verified. Review the stop matches in Google Maps before driving.':'Your selected stops are sent in order. Google Maps may recalculate the roads; EV battery estimates and charging targets stay in EV Route.';$('fullRoute').hidden=!trip.full;if(trip.full){$('fullRoute').href=trip.full;$('fullRoute').textContent=`Open route with all ${trip.count} stops ↗`;}$('exportLimit').textContent=trip.full?(trip.count>3?'Google Maps mobile browsers may omit stops beyond three. If that happens, use the complete mobile-safe trip parts below.':'Your route fits Google Maps’ mobile-browser waypoint limit.'):'This trip exceeds a single Google Maps link’s limits. Use these trip parts in order; every stop is included.';$('tripParts').innerHTML=trip.parts.map((p,i)=>`<a class="trip-part" href="${esc(p.url)}" target="_blank" rel="noopener"><strong>Part ${i+1} ↗</strong><span>${esc(p.from)} → ${esc(p.to)}</span><small>${p.stopLabels.map(esc).join(' → ')}</small></a>`).join('');$('tripPartsDetails').open=!trip.full;$('tripPartsDetails').hidden=trip.parts.length===1&&!!trip.full;$('exportDialog').showModal();}
function chart(){let trace=[{km:0,soc:settings.battery}],prev=0,soc=settings.battery;for(const stop of [...result.stops,{km:route.distance}]){for(const p of route.profile.filter(p=>p.km>prev&&p.km<stop.km))trace.push({km:p.km,soc:soc-legEnergy(route,prev,p.km,settings).energy/settings.capacity*100});const arrival=soc-legEnergy(route,prev,stop.km,settings).energy/settings.capacity*100;trace.push({km:stop.km,soc:arrival});if(stop.target){soc=stop.target;trace.push({km:stop.km,soc});}prev=stop.km;}
const x=k=>40+k/route.distance*600,y=s=>115-s;const path=trace.map((p,i)=>`${i?'L':'M'}${x(p.km).toFixed(1)},${y(p.soc).toFixed(1)}`).join(' ');$('batteryChart').innerHTML=`<svg viewBox="0 0 660 145" role="img" aria-label="Estimated battery along the route, with reserve and charging stops"><defs><linearGradient id="fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#b2d391" stop-opacity=".35"/><stop offset="1" stop-color="#b2d391" stop-opacity=".02"/></linearGradient></defs>${[25,50,75,100].map(s=>`<line x1="40" x2="640" y1="${y(s)}" y2="${y(s)}" stroke="#edf0e9"/><text x="3" y="${y(s)+3}" fill="#8a9585" font-size="9">${s}%</text>`).join('')}<path d="${path} L640,115 L40,115Z" fill="url(#fill)"/><line x1="40" x2="640" y1="${y(result.floor)}" y2="${y(result.floor)}" stroke="#bea267" stroke-dasharray="4 4"/><path d="${path}" stroke="#467751" stroke-width="2.5" fill="none"/>${result.stops.map((p,i)=>`<circle cx="${x(p.km)}" cy="${y(p.target)}" r="4" fill="#467751" stroke="#fff" stroke-width="2"/><text x="${x(p.km)}" y="135" text-anchor="middle" fill="#73826e" font-size="9">Stop ${i+1}</text>`).join('')}<text x="40" y="135" fill="#73826e" font-size="9">Start</text><text x="640" y="135" text-anchor="end" fill="#73826e" font-size="9">${Math.round(route.distance)} km</text></svg>`;}
function render(){planned={origin:settings.origin,destination:settings.destination};dirty=false;$('exportRoute').disabled=false;$('mapButton').disabled=false;$('exportStatus').textContent=`${result.stops.length} charging stops, in order · no API key needed`;$('connectStatus').textContent='';$('mapArt').parentElement.hidden=false;document.querySelectorAll('[data-priority]').forEach(b=>{b.classList.toggle('active',b.dataset.priority===settings.priority);b.setAttribute('aria-pressed',b.dataset.priority===settings.priority);});$('error').hidden=true;$('metrics').innerHTML=[['Journey estimate',time(result.driveMinutes+result.minutes),`${Math.round(route.distance)} km · driving + charging`],['Charging',`${result.stops.length} <small>stops</small>`,`${Math.round(result.minutes)} min incl. stop overhead`],['Charging estimate',`₺${money(result.cost)}`,'Your tariffs · excludes tolls'],['Arrival battery',`${Math.round(result.arrival)}<small>%</small>`,`${settings.reserve}% minimum + ${settings.buffer}% buffer`]].map((m,i)=>`<div class="metric ${i===3?'highlight':''}"><span class="metric-label">${m[0]}</span><strong>${m[1]}</strong><p>${m[2]}</p></div>`).join('');$('chartSubtitle').textContent=`${Math.round(result.payload)} kg payload · ${result.consumption.toFixed(1)} kWh/100 km on level road`;chart();$('stopCount').textContent=result.stops.length;$('stops').innerHTML=result.stops.map((p,i)=>`<article class="stop"><span class="stop-index">${i+1}</span><div><h3>${esc(p.name)}</h3><div class="stop-meta"><span class="network-tag">${esc(p.network)}</span><span>${p.power} kW ${p.power>=50?'DC':'AC'}</span><span>At ${Math.round(p.km)} km</span></div><div class="stop-battery">${Math.round(p.arrival)}% arrival → <strong>${p.target}% departure</strong> · +${p.kwh.toFixed(1)} kWh</div></div><div class="stop-actions"><strong>~${Math.round(p.minutes)} min · ₺${money(p.cost)}</strong><a href="${esc(mapsUrl(p))}" target="_blank" rel="noopener">Open stop ↗</a><button class="exclude" data-exclude="${esc(p.id)}">Exclude & recalculate</button></div></article>`).join('')+`<div class="destination-row"><span>◎ ${esc(settings.destination)}</span><strong>Arrive at ~${Math.round(result.arrival)}%</strong></div>`;$('restoreButton').hidden=!excluded.length;$('modeLabel').textContent=route.source==='sample'?'Sample trip':'Google route';$('modeText').textContent=route.source==='sample'?' · Explore before connecting':' · Road access checked';$('notice').textContent=route.source==='sample'?'Illustrative distances, terrain and charger power. Prices are your assumptions. This sample is not a verified driving itinerary.':'Google route and sampled elevation. Energy is a simplified cruising-speed model; weather and tariffs are manual. Charger coverage may be incomplete. Check availability before driving.';$('mapLabel').textContent=route.source==='sample'?'GOOGLE MAPS':'YOUR GOOGLE ROUTE';$('mapCaption').textContent=route.source==='sample'?'Map connection required':'Google Maps · route through selected stops';$('mapArt').hidden=route.source!=='sample';$('googleMap').hidden=route.source==='sample';document.querySelector('.map-key').hidden=route.source==='sample';if(route.source==='sample')mapSetup();}
function status(t){$('connectStatus').textContent=t;$('modeText').textContent=' · '+t;}
function error(e){invalidate();$('restoreButton').hidden=!excluded.length;$('mapArt').parentElement.hidden=true;$('error').textContent=e.message||String(e);$('error').hidden=false;result=null;$('metrics').innerHTML='';$('batteryChart').innerHTML='';$('stops').innerHTML='<p class="empty">No current plan. Adjust your inputs and calculate again.</p>';$('stopCount').textContent='—';$('chartSubtitle').textContent='';$('connectStatus').textContent=e.message||String(e);$('modeText').textContent=' · Calculation needs attention';}
async function calculate(refresh=false){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{read();validate(settings);if(!settings.origin||!settings.destination)throw Error('Enter both your starting point and destination.');if(settings.mode==='google'){if(refresh||!baseRoute||baseRoute.origin!==settings.origin||baseRoute.destination!==settings.destination)baseRoute=await discover(settings,status);const checked=await verify(baseRoute,settings,excluded,status);route=checked.route;result=checked.result;render();await draw(route);}else{if(settings.origin!==DEFAULTS.origin||settings.destination!==DEFAULTS.destination)throw Error('Connect Google Maps to calculate a different route, or load the Urla example. Sample results only apply to the example inputs.');route=structuredClone(SAMPLE);result=plan(route,settings,excluded);render();}}catch(e){error(e);}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false);$('mapButton').disabled=dirty||!result;$('exportRoute').disabled=dirty||!result;}}
$('tripForm').addEventListener('submit',e=>{e.preventDefault();calculate(true);if(innerWidth<760)$('notice').scrollIntoView({behavior:'smooth',block:'start'});});$('tripForm').addEventListener('input',()=>{syncLabels();invalidate();if(result){$('modeText').textContent=' · Inputs changed — recalculate';$('notice').textContent='Settings changed. The results below reflect your previous calculation. Select “Find my charging stops” to update.';}});$('networks').addEventListener('click',e=>{const n=e.target.dataset.network;if(!n)return;settings.networks=settings.networks.includes(n)?settings.networks.filter(x=>x!==n):[...settings.networks,n];renderNetworks();invalidate();$('modeText').textContent=' · Networks changed — recalculate';});document.querySelectorAll('[data-priority]').forEach(b=>b.addEventListener('click',()=>{settings.priority=b.dataset.priority;calculate();}));$('stops').addEventListener('click',e=>{if(e.target.dataset.exclude){excluded.push(e.target.dataset.exclude);calculate();}});$('restoreButton').onclick=()=>{excluded=[];calculate(true);};$('mapButton').onclick=showExport;$('exportRoute').onclick=showExport;$('connectButton').onclick=()=>{$('connectStatus').textContent='';$('connectionDialog').showModal();};$('vehicleButton').onclick=()=>{$('modelDetails').open=true;$('modelDetails').scrollIntoView({behavior:'smooth',block:'center'});};$('sampleButton').onclick=()=>{settings.mode='sample';settings.origin=DEFAULTS.origin;settings.destination=DEFAULTS.destination;excluded=[];populate();calculate();};$('resetButton').onclick=()=>{settings=structuredClone(DEFAULTS);excluded=[];populate();calculate();};$('locateButton').onclick=()=>{if(!navigator.geolocation)return error(Error('Location is unavailable in this browser.'));navigator.geolocation.getCurrentPosition(p=>{$('origin').value=`${p.coords.latitude.toFixed(6)}, ${p.coords.longitude.toFixed(6)}`;syncLabels();invalidate();$('modeText').textContent=' · Location updated — recalculate';},()=>error(Error('Could not get your location. Allow location access or enter your starting address.')),{enableHighAccuracy:false,timeout:12000});};$('connectNow').onclick=async()=>{const key=$('apiKey').value.trim();if(!key)return $('connectStatus').textContent='Enter a browser-restricted Google Maps key.';$('connectNow').disabled=true;try{status('Connecting to Google Maps…');await connect(key);settings.mode='google';$('apiKey').value='';$('connectionDialog').close();$('connectButton').innerHTML='<span class="status-dot"></span> Google Maps connected ↗';await calculate(true);}catch(e){$('connectStatus').textContent=e.message;}finally{$('connectNow').disabled=false;}};
populate();calculate();
